const numerologyTextsMl = <String, String>{
  // What each number type represents
  'type.lifePath': 'ജീവിതപാത സംഖ്യ മുഴുവൻ ജനനത്തീയതിയിൽ നിന്നാണ് ലഭിക്കുന്നത്. ഒരു ജീവിതകാലത്തിന്റെ പ്രധാന പ്രമേയമായി പാരമ്പര്യം ഇതിനെ വ്യാഖ്യാനിക്കുന്നു: വീണ്ടും വീണ്ടും വരുന്ന പാഠങ്ങൾ, താൽപ്പര്യങ്ങൾ, ദിശ.',
  'type.birthday': 'ജന്മദിന സംഖ്യ മാസത്തിലെ ജനനദിവസത്തിൽ നിന്ന് മാത്രം ലഭിക്കുന്നു. ജീവിതപാതയിലേക്ക് നിങ്ങൾ കൊണ്ടുവരുന്ന ഒരു പ്രത്യേക കഴിവോ പ്രവർത്തനശൈലിയോ ആയി ഇതിനെ വ്യാഖ്യാനിക്കുന്നു.',
